36	Status Version::Load(const std::string &path, Version *version) {
37	  std::ifstream ifs;
38	  ailego::FileHelper::OpenIfstream(ifs, path, std::ios::binary);
39	  if (!ifs.is_open()) {
40	    LOG_ERROR("Failed to open file: %s", path.c_str());
41	    return Status::InternalError("Failed to open file");
42	  }
43	
44	  proto::Manifest manifest;
45	
46	  if (!manifest.ParseFromIstream(&ifs)) {
47	    LOG_ERROR("Failed to parse manifest from file: %s", path.c_str());
48	    return Status::InternalError("Failed to parse manifest");
49	  }
50	
51	  CollectionSchema::Ptr schema = ProtoConverter::FromPb(manifest.schema());
52	  version->set_schema(*schema);
53	
54	  version->set_enable_mmap(manifest.enable_mmap());
55	
56	  for (int i = 0; i < manifest.persisted_segment_metas_size(); ++i) {
57	    SegmentMeta::Ptr meta =
58	        ProtoConverter::FromPb(manifest.persisted_segment_metas(i));
59	    version->add_persisted_segment_meta(meta);
60	  }
61	
62	  if (manifest.has_writing_segment_meta()) {
63	    SegmentMeta::Ptr meta =
64	        ProtoConverter::FromPb(manifest.writing_segment_meta());
65	    version->reset_writing_segment_meta(meta);
66	  }
67	
68	  version->set_id_map_path_suffix(manifest.id_map_path_suffix());
69	  version->set_delete_snapshot_path_suffix(
70	      manifest.delete_snapshot_path_suffix());
71	
72	  version->set_next_segment_id(manifest.next_segment_id());
73	
74	  return Status::OK();
75	}
76	
77	Status Version::Save(const std::string &path, const Version &version) {
78	  std::ofstream ofs;
79	  ailego::FileHelper::OpenOfstream(ofs, path, std::ios::binary);
80	  if (!ofs.is_open()) {
81	    LOG_ERROR("Failed to open file: %s, err: %s", path.c_str(),
82	              ailego::FileHelper::GetLastErrorString().c_str());
83	    return Status::InternalError("Failed to open file: %s", path.c_str());
84	  }
85	
86	  proto::Manifest manifest;
87	
88	  // set schema
89	  auto schema = ProtoConverter::ToPb(version.schema());
90	  manifest.mutable_schema()->Swap(&schema);
91	
92	  manifest.set_enable_mmap(version.enable_mmap());
93	
94	  // set segments meta
95	  for (auto &meta : version.persisted_segment_metas()) {
96	    auto meta_pb = ProtoConverter::ToPb(*meta);
97	    manifest.add_persisted_segment_metas()->Swap(&meta_pb);
98	  }
99	
100	  if (version.writing_segment_meta()) {
101	    auto meta_pb = ProtoConverter::ToPb(*version.writing_segment_meta());
102	    manifest.mutable_writing_segment_meta()->Swap(&meta_pb);
103	  }
104	
105	  manifest.set_id_map_path_suffix(version.id_map_path_suffix());
106	  manifest.set_delete_snapshot_path_suffix(
107	      version.delete_snapshot_path_suffix());
108	  manifest.set_next_segment_id(version.next_segment_id());
109	
110	  if (!manifest.SerializeToOstream(&ofs)) {
111	    LOG_ERROR("Failed to serialize manifest to file: %s", path.c_str());
112	    return Status::InternalError("Failed to serialize manifest to file");
113	  }
114	
115	  return Status::OK();
116	}
