118	std::string Version::to_string() const {
119	  std::ostringstream oss;
120	  oss << "Version{" << "schema:" << (schema_ ? schema_->to_string() : "null")
121	      << ",persisted_segment_metas:[";
122	
123	  size_t i = 0;
124	  for (const auto &pair : persisted_segment_metas_map_) {
125	    if (i > 0) oss << ",";
126	    oss << pair.second->to_string();
127	    ++i;
128	  }
129	
130	  oss << "],writing_segment_meta:";
131	  if (writing_segment_meta_) {
132	    oss << writing_segment_meta_->to_string();
133	  } else {
134	    oss << "null";
135	  }
136	
137	  oss << ",id_map_path_suffix:" << id_map_path_suffix_
138	      << ",delete_snapshot_path_suffix:" << delete_snapshot_path_suffix_
139	      << ",next_segment_id:" << next_segment_id_
140	      << ",enable_mmap:" << enable_mmap_ << "}";
141	  return oss.str();
142	}
