144	std::string Version::to_string_formatted(int indent_level) const {
145	  std::ostringstream oss;
146	  oss << indent(indent_level) << "Version{\n"
147	      << indent(indent_level + 1) << "schema: ";
148	
149	  if (schema_) {
150	    oss << "\n" << schema_->to_string_formatted(indent_level + 2) << "\n";
151	  } else {
152	    oss << "null\n";
153	  }
154	
155	  oss << indent(indent_level + 1) << "persisted_segment_metas: [\n";
156	
157	  size_t i = 0;
158	  for (const auto &pair : persisted_segment_metas_map_) {
159	    oss << pair.second->to_string_formatted(indent_level + 2);
160	    if (i < persisted_segment_metas_map_.size() - 1) {
161	      oss << ",";
162	    }
163	    oss << "\n";
164	    ++i;
165	  }
166	
167	  oss << "\n"
168	      << indent(indent_level + 1) << "],\n"
169	      << indent(indent_level + 1) << "writing_segment_meta: ";
170	
171	  if (writing_segment_meta_) {
172	    oss << "\n"
173	        << writing_segment_meta_->to_string_formatted(indent_level + 2) << "\n";
174	  } else {
175	    oss << "null\n";
176	  }
177	
178	  oss << indent(indent_level + 1)
179	      << "id_map_path_suffix: " << id_map_path_suffix_ << ",\n"
180	      << indent(indent_level + 1)
181	      << "delete_snapshot_path_suffix: " << delete_snapshot_path_suffix_
182	      << ",\n"
183	      << indent(indent_level + 1) << "next_segment_id: " << next_segment_id_
184	      << "\n"
185	      << indent(indent_level + 1) << "enable_mmap: " << enable_mmap_ << "\n"
186	      << indent(indent_level) << "}";
187	  return oss.str();
188	}
