243	Result<VersionManager::Ptr> VersionManager::Create(
244	    const std::string &path, const Version &initial_version) {
245	  VersionManager::Ptr manager =
246	      VersionManager::Ptr(new VersionManager(path, initial_version));
247	  return manager;
248	}
