250	VersionManager::VersionManager(const std::string &path,
251	                               const Version &initial_version,
252	                               uint64_t version_id)
253	    : path_(path), current_version_(initial_version), version_id_(version_id) {}
254	
255	Version VersionManager::get_current_version() {
256	  std::lock_guard lock(mtx_);
257	  return current_version_;
258	}
259	
260	Status VersionManager::apply(const Version &version) {
261	  std::lock_guard lock(mtx_);
262	  current_version_ = version;
263	  return Status::OK();
264	}
265	
266	Status VersionManager::reset_writing_segment_meta(SegmentMeta::Ptr meta) {
267	  std::lock_guard lock(mtx_);
268	  current_version_.reset_writing_segment_meta(meta);
269	  return Status::OK();
270	}
271	
272	Status VersionManager::add_persisted_segment_meta(SegmentMeta::Ptr meta) {
273	  std::lock_guard lock(mtx_);
274	  return current_version_.add_persisted_segment_meta(meta);
275	}
276	
277	Status VersionManager::remove_persisted_segment_meta(SegmentID id) {
278	  std::lock_guard lock(mtx_);
279	  return current_version_.remove_persisted_segment_meta(id);
280	}
281	
282	Status VersionManager::flush() {
283	  std::lock_guard lock(mtx_);
284	
285	  std::string current_path;
286	  if (version_id_ != 0) {
287	    current_path =
288	        FileHelper::MakeFilePath(path_, FileID::MANIFEST_FILE, version_id_ - 1);
289	  }
290	
291	  auto s = Version::Save(
292	      FileHelper::MakeFilePath(path_, FileID::MANIFEST_FILE, version_id_++),
293	      current_version_);
294	  CHECK_RETURN_STATUS(s);
295	
296	  if (!current_path.empty()) {
297	    FileHelper::RemoveFile(current_path);
298	  }
299	
300	  return Status::OK();
301	}
