627	std::vector<SegmentTask::Ptr> CollectionImpl::build_drop_fts_index_task(
628	    const std::vector<Segment::Ptr> &segments, const std::string &column) {
629	  std::vector<SegmentTask::Ptr> tasks;
630	  for (auto &segment : segments) {
631	    tasks.push_back(
632	        SegmentTask::CreateDropFtsIndexTask(DropFtsIndexTask{segment, column}));
633	  }
634	  return tasks;
